using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace CybersecurityChatbotGUI.Models
{
    public class CyberTask
    {
        // Database ID generated by MySQL.
        public int TaskId { get; set; }

        // Short task name, for example: Enable two-factor authentication.
        public string Title { get; set; } = "";

        // More detailed explanation of the task.
        public string Description { get; set; } = "";

        // Nullable because a task reminder is optional.
        public DateTime? ReminderDate { get; set; }

        // False means pending. True means completed.
        public bool IsCompleted { get; set; }
    }
}